subscribe(PUB_SUB_EVENTS.cartUpdate,(()=>{fetch(window.location.pathname+"?section_id=cart-progress-bar").then((e=>e.text())).then((e=>{const t=undefined,r=undefined,n=(new DOMParser).parseFromString(e,"text/html").querySelector(".cart-progress--section");if(n){const e=undefined;document.querySelector(".cart-progress--section").replaceWith(n)}})).catch((e=>{}))}));